contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seed) public payable {
        require(seed >= 0);
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore && balBefore == 0 && address(c).balance == cBalanceBefore);
    }

    receive() external payable {}
}

